+/**
+ * Soft delete a conversation (reset chat)
+ * This preserves the conversation history in the database but makes it inaccessible
+ */
+export async function softDeleteConversation(
+  canvasDraftId: string
+): Promise<{ success: boolean; error?: string }> {
+  try {
+    const user = await currentUser();
+    if (!user?.id) {
+      return { success: false, error: 'Unauthorized' };
+    }
+
+    // Soft delete the active conversation
+    const result = await prisma.canvasChatConversation.updateMany({
+      where: {
+        canvasDraftId,
+        userId: user.id,
+        deletedAt: null
+      },
+      data: {
+        deletedAt: new Date(),
+        deletedBy: user.id
+      }
+    });
+
+    logger.info('Soft deleted chat conversation', {
+      canvasDraftId,
+      userId: user.id,
+      conversationsDeleted: result.count
+    });
+
+    return { success: true };
+  } catch (error) {
+    logger.error(
+      'Error soft deleting conversation',
+      error instanceof Error ? error : { cause: String(error) }
+    );
+    return {
+      success: false,
+      error: error instanceof Error ? error.message : 'Unknown error'
+    };
+  }
+}
